After (using OpenZeppelin's TimelockController):
// This requires integrating with TimelockController, where the contract owner is the timelock.
// The owner would queue a transaction and execute it after the delay.
// A simpler alternative is a custom timelock:

address public pendingGameSigner;
uint256 public gameSignerChangeTime;

function setGameSigner(address _signer) external onlyOwner {
    require(_signer != address(0), "Invalid signer");
    pendingGameSigner = _signer;
    gameSignerChangeTime = block.timestamp + 48 hours; // 2 day delay
    // Emit event
}

function executeSetGameSigner() external {
    require(block.timestamp >= gameSignerChangeTime, "Timelock active");
    require(pendingGameSigner != address(0), "No pending change");
    gameSigner = pendingGameSigner;
    delete pendingGameSigner;
    delete gameSignerChangeTime;
    // Emit event
}

